/**  Операции правки таймлайна (пакет — один шаг истории). */
export type Op = { op: "addClip"; track: string; kind: ClipKind; src: string | null; text: string | null; start: number; duration: number; offset: number | null } | 
/**  Видео со звуком: клип картинки и связанный клип звука того же файла. */
{ op: "addLinked"; videoTrack: string; audioTrack: string; src: string; start: number; duration: number; offset: number | null } | { op: "moveClip"; id: string; track: string | null; start: number } | 
/**  Новые границы: `start`/`duration` на таймлайне и `offset` в файле (что не задано — как было). */
{ op: "trimClip"; id: string; start: number | null; duration: number | null; offset: number | null } | 
/**  Разрезать клип в кадре таймлайна. */
{ op: "splitClip"; id: string; at: number } | 
/**  Удалить клипы; `ripple` — сдвинуть следующие клипы тех же дорожек влево на освободившееся. */
{ op: "deleteClips"; ids: string[]; ripple: boolean } | 
/**  Изменить свойства: незаданные остаются как были. */
{ op: "setProps"; id: string; props: ClipPropsPatch } | { op: "setText"; id: string; text: string } | { op: "setTrack"; id: string; muted?: boolean | null; locked?: boolean | null; volume?: number | null; captionMode?: CaptionMode | null } | 
/**  Новая дорожка: видео — наверх стопки, звук — вниз. Дорожка субтитров одна. */
{ op: "addTrack"; kind: TrackKind } | 
/**  Убрать пустую дорожку (последнюю дорожку вида и субтитры нельзя). */
{ op: "removeTrack"; id: string } | 
/**
 *  Копии клипов (связанные — вместе); `at` — куда встанет самый ранний, иначе сразу за концом
 *  копируемых.
 */
{ op: "duplicateClips"; ids: string[]; at?: number | null } | 
/**  Клипы наверх или вниз своих дорожек: верхний перекрывает нижний при наложении. */
{ op: "arrangeClips"; ids: string[]; top: boolean } | 
/**  Связать клипы (двигаются вместе) или развязать. */
{ op: "setLink"; ids: string[]; linked: boolean } | 
/**  Наложить эффект на клип. */
{ op: "addEffect"; clip: string; effect: AppliedEffect } | 
/**  Изменить эффект на клипе: значения (добавляются к прежним), вкл/выкл, панель, анимацию. */
{ op: "setEffect"; clip: string; fx: string; params?: any; enabled?: boolean | null; controls?: any; spec?: any } | { op: "removeEffect"; clip: string; fx: string } | 
/**  Эффект на всю дорожку (и на будущие клипы). */
{ op: "addTrackEffect"; track: string; effect: AppliedEffect } | { op: "setTrackEffect"; track: string; fx: string; params?: any; enabled?: boolean | null; controls?: any; spec?: any } | { op: "removeTrackEffect"; track: string; fx: string } | 
/**
 *  Одна правка на много клипов по условию `select` (вместо операции на каждый): свойства; значения
 *  или вкл/выкл эффекта библиотеки `effect`; наложить `add`; снять `removeEffect`.
 */
{ op: "editWhere"; select: ClipFilter; props?: ClipPropsPatch | null; effect?: string | null; params?: any; enabled?: boolean | null; add?: AppliedEffect | null; removeEffect?: string | null } | { op: "addMarker"; frame: number; label: string } | { op: "removeMarker"; frame: number };

